-- Test-only Supabase platform substrate. Never deploy this fixture.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create schema storage;
create schema realtime;
create schema extensions;
grant usage on schema public,auth,storage,realtime,extensions to anon,authenticated,service_role;
alter default privileges in schema public grant all on tables to anon,authenticated,service_role;
alter default privileges in schema public grant all on sequences to anon,authenticated,service_role;
alter default privileges in schema public grant execute on functions to anon,authenticated,service_role;
create table auth.users(id uuid primary key, email text, email_confirmed_at timestamptz, invited_at timestamptz, raw_user_meta_data jsonb default '{}');
create table auth.mfa_factors(id uuid primary key, user_id uuid references auth.users, factor_type text, status text, created_at timestamptz, updated_at timestamptz);
create table auth.sessions(id uuid primary key, user_id uuid references auth.users, not_after timestamptz);
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb $$;
create function auth.uid() returns uuid language sql stable as $$ select (auth.jwt()->>'sub')::uuid $$;
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text references storage.buckets,name text);
alter table storage.objects enable row level security;
grant all on storage.objects to authenticated,service_role;
create function storage.foldername(name text) returns text[] language sql immutable as $$ select (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1] $$;
create table realtime.messages(id bigint generated always as identity,extension text);
alter table realtime.messages enable row level security;
grant all on realtime.messages to authenticated,service_role;
create function realtime.topic() returns text language sql stable as $$ select current_setting('realtime.topic',true) $$;
create publication supabase_realtime;
set search_path=public,extensions;
